import{_ as a,a0 as p,w as d,s as i,ao as l,I as s,x as r,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse(`{"title":"在 RHEL/CentOS 上為Web服務器架設 “XR”（Crossroads） 負載均衡器 | LCTT x X-CMD","titleTemplate":false,"description":"在 RHEL/CentOS 上為Web服務器架設 “XR”（Crossroads） 負載均衡器 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 RHEL/CentOS 上為Web服務器架設 “XR”（Crossroads） 負載均衡器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 RHEL/CentOS 上為Web服務器架設 “XR”（Crossroads） 負載均衡器 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150717 Setting Up 'XR' (Crossroads) Load Balancer for Web Servers on RHEL or CentOS","title":"在 RHEL/CentOS 上為Web服務器架設 “XR”（Crossroads） 負載均衡器","tag":"201507","desc":""},"relativePath":"201507/20150717 Setting Up 'XR' (Crossroads) Load Balancer for Web Servers on RHEL or CentOS.md","filePath":"[post].md"}`),m={name:"201507/20150717 Setting Up 'XR' (Crossroads) Load Balancer for Web Servers on RHEL or CentOS.md"};function g(u,t,w,R,b,C){const e=p("Link");return d(),i("div",null,[t[29]||(t[29]=l(`<h1 id="在-rhel-centos-上為web服務器架設-xr-crossroads-負載均衡器" tabindex="-1">在 RHEL/CentOS 上為Web服務器架設 “XR”（Crossroads） 負載均衡器 <a class="header-anchor" href="#在-rhel-centos-上為web服務器架設-xr-crossroads-負載均衡器" aria-label="Permalink to “在 RHEL/CentOS 上為Web服務器架設 “XR”（Crossroads） 負載均衡器”">​</a></h1><p>Crossroads 是一個獨立的服務，它是一個用於Linux和TCP服務的開源負載均衡和故障轉移實用程序。它可用於HTTP，HTTPS，SSH，SMTP 和 DNS 等，它也是一個多線程的工具，在提供負載均衡服務時，它可以只使用一塊內存空間以此來提高性能。</p><p>首先來看看 XR 是如何工作的。我們可以將 XR 放到網絡客户端和服務器之間，它可以將客户端的請求分配到服務器上以平衡負載。</p><p>如果一台服務器宕機，XR 會轉發客户端請求到另一個服務器，所以客户感覺不到停頓。看看下面的圖來了解什麼樣的情況下，我們要使用 XR 處理。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Install-XR-Crossroads-Load-Balancer.jpg" alt="Install XR Crossroads Load Balancer"></p><p><em>安裝 XR Crossroads 負載均衡器</em></p><p>這裏有兩個 Web 服務器，一個網關服務器，我們將在網關服務器上安裝和設置 XR 以接收客户端請求，並分發到服務器。</p><p>XR Crossroads 網關服務器：172.16.1.204</p><p>Web 服務器01：172.16.1.222</p><p>Web 服務器02：192.168.1.161</p><p>在上述情況下，我們網關服務器（即 XR Crossroads）的IP地址是172.16.1.222，webserver01 為172.16.1.222，它監聽8888端口，webserver02 是192.168.1.161，它監聽端口5555。</p><p>現在，我們需要的是均衡所有的請求，通過 XR 網關從網上接收請求然後分發它到兩個web服務器已達到負載均衡。</p><h3 id="第1步-在網關服務器上安裝-xr-crossroads-負載均衡器" tabindex="-1">第1步：在網關服務器上安裝 XR Crossroads 負載均衡器 <a class="header-anchor" href="#第1步-在網關服務器上安裝-xr-crossroads-負載均衡器" aria-label="Permalink to “第1步：在網關服務器上安裝 XR Crossroads 負載均衡器”">​</a></h3><p><strong>1. 不幸的是，沒有為 crossroads 提供可用的 RPM 包，我們只能從源碼安裝。</strong></p><p>要編譯 XR，你必須在系統上安裝 C++ 編譯器和 GNU make 組件，才能避免安裝錯誤。</p><pre><code># yum install gcc gcc-c++ make
</code></pre>`,16)),s("p",null,[t[2]||(t[2]=r("接下來，去他們的官方網站（[",-1)),o(e,{href:"https://crossroads.e-tunity.com"},{default:n(()=>[...t[0]||(t[0]=[r("https://crossroads.e-tunity.com",-1)])]),_:1}),t[3]||(t[3]=r("] ",-1)),o(e,{href:"https://crossroads.e-tunity.com/"},{default:n(()=>[...t[1]||(t[1]=[r("1",-1)])]),_:1}),t[4]||(t[4]=r("）下載此壓縮包（即 crossroads-stable.tar.gz）。",-1))]),t[30]||(t[30]=s("p",null,"或者，您可以使用 wget 去下載包然後解壓在任何位置（如：/usr/src/），進入解壓目錄，並使用 “make install” 命令安裝。",-1)),t[31]||(t[31]=s("pre",null,[s("code",null,`# wget https://crossroads.e-tunity.com/downloads/crossroads-stable.tar.gz
# tar -xvf crossroads-stable.tar.gz
# cd crossroads-2.74/
# make install
`)],-1)),t[32]||(t[32]=s("p",null,[s("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/07/Install-XR-Crossroads-Load-Balancer.png",alt:"Install XR Crossroads Load Balancer"})],-1)),t[33]||(t[33]=s("p",null,[s("em",null,"安裝 XR Crossroads 負載均衡器")],-1)),t[34]||(t[34]=s("p",null,"安裝完成後，二進制文件安裝在 /usr/sbin 目錄下，XR 的配置文件在 /etc 下名為 “xrctl.xml” 。",-1)),t[35]||(t[35]=s("p",null,[s("strong",null,"2. 最後一個條件，你需要兩個web服務器。為了方便使用，我在一台服務器中創建兩個 Python SimpleHTTPServer 實例。")],-1)),s("p",null,[t[6]||(t[6]=r("要了解如何設置一個 python SimpleHTTPServer，請閲讀我們此處的文章 ",-1)),o(e,{href:"http://www.tecmint.com/python-simplehttpserver-to-create-webserver-or-serve-files-instantly/"},{default:n(()=>[...t[5]||(t[5]=[r("使用 SimpleHTTPServer 輕鬆創建兩個 web 服務器",-1)])]),_:1}),t[7]||(t[7]=r(".",-1))]),t[36]||(t[36]=l('<p>正如我所説的，我們要使用兩個web服務器，webserver01 通過8888端口運行在172.16.1.222上，webserver02 通過5555端口運行在192.168.1.161上。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/XR-WebServer01.jpg" alt="XR WebServer 01"></p><p><em>XR WebServer 01</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/XR-WebServer02.jpg" alt="XR WebServer 02"></p><p><em>XR WebServer 02</em></p><h3 id="第2步-配置-xr-crossroads-負載均衡器" tabindex="-1">第2步: 配置 XR Crossroads 負載均衡器 <a class="header-anchor" href="#第2步-配置-xr-crossroads-負載均衡器" aria-label="Permalink to “第2步: 配置 XR Crossroads 負載均衡器”">​</a></h3><p><strong>3. 所需都已經就緒。現在我們要做的就是配置<code>xrctl.xml</code> 文件並通過 XR 服務器接受來自互聯網的請求分發到 web 服務器上。</strong></p>',7)),s("p",null,[t[9]||(t[9]=r("現在用 ",-1)),o(e,{href:"http://www.tecmint.com/vi-editor-usage/"},{default:n(()=>[...t[8]||(t[8]=[r("vi/vim 編輯器",-1)])]),_:1}),t[10]||(t[10]=r("打開",-1)),t[11]||(t[11]=s("code",null,"xrctl.xml",-1)),t[12]||(t[12]=r("文件。",-1))]),t[37]||(t[37]=l(`<pre><code># vim /etc/xrctl.xml
</code></pre><p>並作如下修改。</p><pre><code>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;
&lt;configuration&gt;
&lt;system&gt;
&lt;uselogger&gt;true&lt;/uselogger&gt;
&lt;logdir&gt;/tmp&lt;/logdir&gt;
&lt;/system&gt;
&lt;service&gt;
&lt;name&gt;Tecmint&lt;/name&gt;
&lt;server&gt;
&lt;address&gt;172.16.1.204:8080&lt;/address&gt;
&lt;type&gt;tcp&lt;/type&gt;
&lt;webinterface&gt;0:8010&lt;/webinterface&gt;
&lt;verbose&gt;yes&lt;/verbose&gt;
&lt;clientreadtimeout&gt;0&lt;/clientreadtimeout&gt;
&lt;clientwritetimout&gt;0&lt;/clientwritetimeout&gt;
&lt;backendreadtimeout&gt;0&lt;/backendreadtimeout&gt;
&lt;backendwritetimeout&gt;0&lt;/backendwritetimeout&gt;
&lt;/server&gt;
&lt;backend&gt;
&lt;address&gt;172.16.1.222:8888&lt;/address&gt;
&lt;/backend&gt;
&lt;backend&gt;
&lt;address&gt;192.168.1.161:5555&lt;/address&gt;
&lt;/backend&gt;
&lt;/service&gt;
&lt;/configuration&gt;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Configure-XR-Crossroads-Load-Balancer.jpg" alt="Configure XR Crossroads Load Balancer"></p><p><em>配置 XR Crossroads 負載均衡器</em></p><p>在這裏，你可以看到在 xrctl.xml 中配置了一個非常基本的 XR 。我已經定義了 XR 服務器在哪裏，XR 的後端服務和端口及 XR 的 web 管理界面是什麼。</p><p><strong>4. 現在，你需要通過以下命令來啓動該 XR 守護進程。</strong></p><pre><code># xrctl start
# xrctl status
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Start-XR-Crossroads.jpg" alt="Start XR Crossroads"></p><p><em>啓動 XR Crossroads</em></p><p><strong>5. 好的。現在是時候來檢查該配置是否可以工作正常了。打開兩個網頁瀏覽器，輸入 XR 服務器的 IP 地址和端口，並查看輸出。</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Verify-Web-Server-Load-Balancing.jpg" alt="Verify Web Server Load Balancing"></p><p><em>驗證 Web 服務器負載均衡</em></p><p>太棒了。它工作正常。是時候玩玩 XR 了。（LCTT 譯註：可以看到兩個請求分別分配到了不同服務器。）</p><p><strong>6. 現在可以通過我們配置的網絡管理界面的端口來登錄到 XR Crossroads 儀表盤。在瀏覽器輸入你的 XR 服務器的 IP 地址和你配置在 xrctl.xml 中的管理端口。</strong></p><pre><code>http://172.16.1.204:8010
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/XR-Crossroads-Dashboard.jpg" alt="XR Crossroads Dashboard"></p><p><em>XR Crossroads 儀表盤</em></p><p>看起來像上面一樣。它容易理解，用户界面​​友好，易於使用。它在右上角顯示每個服務器能容納多少個連接，以及關於接收該請求的附加細節。你也可以設置每個服務器承擔的負載量，最大連接數和平均負載等。</p><p>最大的好處是，即使沒有配置文件 xrctl.xml，你也可以做到這一點。你唯一要做的就是運行以下命令，它就會把這一切搞定。</p><pre><code># xr --verbose --server tcp:172.16.1.204:8080 --backend 172.16.1.222:8888 --backend 192.168.1.161:5555
</code></pre><p>上面語法的詳細説明：</p><ul><li>-verbose 將顯示命令執行後的信息。</li><li>-server 定義你在安裝包中的 XR 服務器。</li><li>-backend 定義你需要平衡分配到 Web 服務器的流量。</li><li>tcp 説明我們使用 TCP 服務。</li></ul>`,23)),s("p",null,[t[14]||(t[14]=r("欲瞭解更多詳情，有關文件及 CROSSROADS 的配置，請訪問他們的官方網站: ",-1)),o(e,{href:"https://crossroads.e-tunity.com/"},{default:n(()=>[...t[13]||(t[13]=[r("https://crossroads.e-tunity.com/",-1)])]),_:1}),t[15]||(t[15]=r(".",-1))]),t[38]||(t[38]=s("p",null,"XR Corssroads 使用許多方法來提高服務器性能，避免宕機，讓你的管理任務更輕鬆，更簡便。希望你喜歡此文章，並隨時在下面發表你的評論和建議，方便與我們保持聯繫。",-1)),t[39]||(t[39]=s("hr",null,null,-1)),s("p",null,[t[17]||(t[17]=r("via: ",-1)),o(e,{href:"http://www.tecmint.com/setting-up-xr-crossroads-load-balancer-for-web-servers-on-rhel-centos/"},{default:n(()=>[...t[16]||(t[16]=[r("http://www.tecmint.com/setting-up-xr-crossroads-load-balancer-for-web-servers-on-rhel-centos/",-1)])]),_:1})]),s("p",null,[t[21]||(t[21]=r("作者：",-1)),o(e,{href:"http://www.tecmint.com/author/thilidhanushka/"},{default:n(()=>[...t[18]||(t[18]=[r("Thilina Uvindasiri",-1)])]),_:1}),t[22]||(t[22]=r(" 譯者：",-1)),o(e,{href:"https://github.com/strugglingyouth"},{default:n(()=>[...t[19]||(t[19]=[r("strugglingyouth",-1)])]),_:1}),t[23]||(t[23]=r(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[20]||(t[20]=[r("wxy",-1)])]),_:1})]),s("p",null,[t[26]||(t[26]=r("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[24]||(t[24]=[r("LCTT",-1)])]),_:1}),t[27]||(t[27]=r(" 原創翻譯，",-1)),o(e,{href:"https://linux.cn/"},{default:n(()=>[...t[25]||(t[25]=[r("Linux中國",-1)])]),_:1}),t[28]||(t[28]=r(" 榮譽推出",-1))])])}const f=a(m,[["render",g]]);export{T as __pageData,f as default};
